namespace sv_11e30d8daa53455da1b20ce192ff63fd.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

public sealed class ThemeState
{
    public ThemeMode Mode { get; init; } = ThemeMode.System;
    public string AccentColor { get; init; } = "#0d6efd";
}

/// <summary>
/// Scoped service — each SignalR circuit (user) gets its own instance.
/// Holds the current theme and notifies subscribers when it changes.
/// </summary>
public sealed class ThemeService
{
    private ThemeState _state = new();

    public ThemeState Current => _state;

    public event Action? OnChange;

    public void SetTheme(ThemeMode mode)
    {
        if (_state.Mode == mode) return;
        _state = _state with { Mode = mode };
        OnChange?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        if (_state.AccentColor == color) return;
        _state = _state with { AccentColor = color };
        OnChange?.Invoke();
    }

    public void Update(ThemeMode mode, string accentColor)
    {
        if (_state.Mode == mode && _state.AccentColor == accentColor) return;
        _state = new ThemeState { Mode = mode, AccentColor = accentColor };
        OnChange?.Invoke();
    }
}

