                    var isActive = ThemeState.Mode == mode;
                    <button type="button"
                            class="btn @(isActive ? "btn-primary" : "btn-outline-primary")"
                            @onclick="() => ThemeService.SetTheme(mode)">
                        @mode
                    </button>
                }
            </div>
        </div>

        <div class="mb-3">
            <label class="form-label" for="accent-color">Accent Color</label>
            <div class="d-flex align-items-center gap-2">
                <input id="accent-color"
                       type="color"
                       class="form-control form-control-color"
                       value="@ThemeState.AccentColor"
                       @onchange="OnAccentColorChanged" />
                <span class="text-muted">@ThemeState.AccentColor</span>
            </div>
        </div>

        <div class="alert alert-info mt-3 mb-0" style="border-left: 4px solid @ThemeState.AccentColor;">
            <strong>Preview:</strong> Current theme is <strong>@ThemeState.Mode</strong>
            with accent <span style="color: @ThemeState.AccentColor;">@ThemeState.AccentColor</span>.
            <br />Changes are applied immediately to all components.
        </div>
    </div>
</div>

@code {
    [CascadingParameter] public Services.ThemeState ThemeState { get; set; } = default!;

    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void OnAccentColorChanged(ChangeEventArgs e)
    {
        if (e.Value is string color)
        {
            ThemeService.SetAccentColor(color);
        }
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

